// Concatenates every migration plus the demo account into supabase/setup.sql,
// so the whole database can be set up with one paste into the Supabase SQL Editor.
// Usage: node scripts/build-setup-sql.mjs
import { readdirSync, readFileSync, writeFileSync } from "node:fs";

const dir = "supabase/migrations";
const parts = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort().map((f) => [f, readFileSync(`${dir}/${f}`, "utf8")]);
parts.push(["demo_user.sql", readFileSync("supabase/demo_user.sql", "utf8")]);

const out = [
  "-- Capital 50 AI: full database setup. Generated by scripts/build-setup-sql.mjs; do not edit by hand.",
  "-- Paste all of it into Supabase > SQL Editor and press Run. Safe to run again.",
  ...parts.map(([f, sql]) => `\n-- ======================================================== ${f}\n${sql.trim()}\n`),
].join("\n");
writeFileSync("supabase/setup.sql", out);
console.log(`wrote supabase/setup.sql (${parts.length} parts, ${Math.round(out.length / 1024)} KB)`);
